/**
 * @param {import('./internal').Component} component
 * @param {boolean} replay
 */
ComponentHooks.prototype.prepareRender = function(component, replay) {
	if (replay) {
		this._pendingEffects = [];
		component._renderCallbacks = [];
		this._list.forEach(hookItem => {
			if (hookItem._args || hookItem._factory) {
				hookItem._args = undefined;
			}
			if (hookItem._component) {
				hookItem._component = component;
			}
		});
	} else {
		this._pendingEffects.forEach(hookItem => {
			const previous = currentComponent;
			let cleanup = hookItem._cleanup;
			if (typeof cleanup == 'function') {
				hookItem._cleanup = undefined;
				cleanup();
			}
			currentComponent = previous;
		});
		this._pendingEffects.forEach(hookItem => {
			const previous = currentComponent;
			hookItem._cleanup = hookItem._value();
			currentComponent = previous;
		});
		this._pendingEffects = [];
	}
};

options._diff = vnode => {
	currentComponent = null;
	if (oldBeforeDiff) oldBeforeDiff(vnode);
};

options._render = vnode => {
	if (oldBeforeRender) oldBeforeRender(vnode);

	currentComponent = vnode._component;
	currentIndex = 0;

	const hooks = currentComponent.__hooks;
	if (hooks) {
		hooks.prepareRender(
			currentComponent,
			previousComponent === currentComponent
